const express = require("express");
const router = express.Router();
const User = require("../models/User"); // ✅ Import mô hình User
const bcrypt = require("bcrypt");
const jwt = require("jsonwebtoken");

// Lấy JWT Secret từ môi trường (ENV)
// ⚠️ QUAN TRỌNG: KHÔNG ĐƯỢC ĐẶT GIÁ TRỊ MẶC ĐỊNH MẠNH Ở ĐÂY
const JWT_SECRET = process.env.JWT_SECRET; 

// ⚠️ KIỂM TRA ĐỂ ĐẢM BẢO JWT_SECRET TỒN TẠI TRONG .ENV
if (!JWT_SECRET) {
  console.error("LỖI CẤU HÌNH: Cần định nghĩa JWT_SECRET trong file .env!");
  // Thoát ứng dụng hoặc sử dụng một khóa tạm thời (không an toàn)
  throw new Error("Cần định nghĩa JWT_SECRET trong file .env!");
}

// ---------------------
// ✅ HÀM TẠO TOKEN
// ---------------------
const generateToken = (id) => {
  return jwt.sign({ id }, JWT_SECRET, {
    expiresIn: "30d", // Token hết hạn sau 30 ngày
  });
};

// ---------------------
// ĐĂNG KÝ
// ---------------------
router.post("/register", async (req, res) => {
  try {
    const {
      fullName,
      email,
      password,
      gender,
      birthDay,
      birthMonth,
      birthYear,
      role,
    } = req.body;

    // Kiểm tra email tồn tại (Giả định Mongoose)
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res.status(400).json({ message: "Email đã tồn tại!" });
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(password, 10);

    const newUser = new User({
      fullName,
      email,
      password: hashedPassword,
      gender,
      birthDay,
      birthMonth,
      birthYear,
      role: role || "user", // Đảm bảo luôn có role mặc định
    });

    await newUser.save();

    res.status(201).json({
      message: "Đăng ký thành công!",
      user: {
        id: newUser._id,
        fullName: newUser.fullName,
        email: newUser.email,
        role: newUser.role,
      },
    });
  } catch (error) {
    console.error("Lỗi đăng ký:", error);
    res.status(500).json({ message: "Lỗi Server nội bộ khi đăng ký." });
  }
});

// ---------------------
// ĐĂNG NHẬP
// ---------------------
router.post("/login", async (req, res) => {
  try {
    const { email, password } = req.body;

    // 🔥 SỬA LỖI CÚ PHÁP: Giả định Mongoose. Loại bỏ 'where:'
    // Đồng thời dùng .select('+password') nếu bạn ẩn password trong Model
    const user = await User.findOne({ email }).select("+password"); 

    if (!user) {
      return res.status(400).json({ message: "Email không tồn tại!" });
    }

    // Kiểm tra password
    // Lưu ý: Nếu dùng Mongoose/Sequelize, user.password phải chứa hashed password
    const valid = await bcrypt.compare(password, user.password);
    if (!valid) {
      return res.status(400).json({ message: "Sai mật khẩu!" });
    }

    // ✅ LOGIN THÀNH CÔNG: TẠO TOKEN
    const token = generateToken(user._id);

    // Đảm bảo ẩn password trước khi trả về
    user.password = undefined;

    res.json({
      message: "Đăng nhập thành công",
      role: user.role,
      token: token, // <-- TOKEN THẬT
      user: {
        id: user._id,
        fullName: user.fullName,
        role: user.role, // Thêm role vào user object để dễ dùng ở Frontend
      },
    });
  } catch (error) {
    console.error("Lỗi đăng nhập:", error);
    res.status(500).json({ message: "Lỗi Server nội bộ khi đăng nhập." });
  }
});

// ---------------------
// EXPORT
// ---------------------

// Export cả router và hàm tạo token để các phần khác có thể sử dụng (ví dụ: test)
module.exports = { router, generateToken };